Use a mutex and condition variable:

```cpp
template<typename T>
class ThreadSafeQueue {
    queue<T> q;
    mutex m;
    condition_variable cv;
public:
    void push(T val) {
        lock_guard<mutex> lock(m);
        q.push(val);
        cv.notify_one();
    }

    T pop() {
        unique_lock<mutex> lock(m);
        cv.wait(lock, [this]{ return !q.empty(); });
        T val = q.front(); q.pop();
        return val;
    }
};
```
